<template>
  <el-dialog
    title="作品水印"
    :visible.sync="dialogFormVisible"
    v-if="dialogFormVisible"
  >
    <el-form ref="watermarkSettingForm" :model="form" :inline="true">
      <el-form-item label="状态" :label-width="formLabelWidth">
        <el-switch
          v-model="form.status"
          active-color="#13ce66"
          inactive-color="#ff4949"
          :active-value="1"
          :inactive-value="0"
        >
        </el-switch>
      </el-form-item>
      <el-form-item label="水印文字" :label-width="formLabelWidth">
        <el-input
          type="text"
          placeholder="请输入水印文字"
          v-model="form.content"
          maxlength="200"
          show-word-limit
          class="water-txt-input"
        />
      </el-form-item>
      <h3>示例展示:</h3>
      <div class="demo-watermark">
        <div class="block">
          <span class="demonstration">添加前</span>
          <el-image
            :src="require('@/assets/demo/no-watermark.jpeg')"
          ></el-image>
        </div>
        <div class="block">
          <span class="demonstration">添加后</span>
          <el-image :src="require('@/assets/demo/watermarked.jpeg')">
          </el-image>
        </div>
      </div>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="onCancel">取 消</el-button>
      <el-button type="primary" @click="onSave">确 定</el-button>
    </div>
  </el-dialog>
</template>
  
  <script>
// eslint-disable-next-line no-unused-vars
import { getProductConfig, setProductConfig } from '@/api/vr'
const defaultForm = {
  status: 1,
  content: '',
  color: '',
}
export default {
  name: 'watermarkConfig',
  data() {
    return {
      dialogFormVisible: false,
      form: Object.assign({}, defaultForm),
      formLabelWidth: '120px',
    }
  },
  props: {
    productId: null,
  },
  methods: {
    async init() {
      this.dialogFormVisible = true
      await this.getConfig()
    },
    async getConfig() {
      const config = await getProductConfig(this.productId, 'product_watermark')
      if (config) {
        this.form = config.val
      }
    },
    onCancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.watermarkSettingForm.resetFields()
      this.dialogFormVisible = false
    },
    onSave() {
      this.$refs.watermarkSettingForm.validate((valid) => {
        if (valid) {
          setProductConfig(this.productId, 'product_watermark', this.form).then(
            (data, message) => {
              console.log('data, message:', data, message)
              this.$message.success('设置成功')
              this.onCancel()
            }
          )
        } else {
          return false
        }
      })
    },
  },
}
</script>
<style lang="less" scoped>
.water-txt-input {
  width: 200px;
}
.demo-watermark {
  display: flex;
  flex: 1;
  gap: 20px;
  .block {
    text-align: center;
  }
}
</style>